import { OPENWIKI_REASONING_EFFORT_ENV_KEY, providerUsesResponsesApi, resolveOpenAiCompatibleReasoningEffortSupported, } from "./constants.js";
export const REASONING_EFFORT_VALUES = [
    "none",
    "low",
    "medium",
    "high",
    "xhigh",
    "max",
];
const OPENAI_GPT_56_REASONING_CAPABILITY = {
    transport: "responses-reasoning",
    values: REASONING_EFFORT_VALUES,
};
const GEMINI_THINKING_LEVEL_REASONING_CAPABILITY = {
    transport: "gemini-thinking-level",
    values: ["low", "medium", "high"],
};
const REASONING_CAPABILITIES = {
    openai: {
        "gpt-5.6-terra": OPENAI_GPT_56_REASONING_CAPABILITY,
        "gpt-5.6-luna": OPENAI_GPT_56_REASONING_CAPABILITY,
        "gpt-5.6-sol": OPENAI_GPT_56_REASONING_CAPABILITY,
    },
    "openai-chatgpt": {
        "gpt-5.6-terra": OPENAI_GPT_56_REASONING_CAPABILITY,
        "gpt-5.6-luna": OPENAI_GPT_56_REASONING_CAPABILITY,
        "gpt-5.6-sol": OPENAI_GPT_56_REASONING_CAPABILITY,
    },
    nvidia: {
        "nvidia/nemotron-3-super-120b-a12b": {
            transport: "chat-completions-reasoning-effort",
            values: ["none", "low", "high"],
        },
    },
    gemini: {
        "gemini-3.6-flash": GEMINI_THINKING_LEVEL_REASONING_CAPABILITY,
    },
};
export function getReasoningCapability(provider, modelId, env = process.env) {
    if (provider === "openai-compatible") {
        return getOpenAiCompatibleReasoningCapability(modelId, env);
    }
    return REASONING_CAPABILITIES[provider]?.[modelId];
}
export function isReasoningEffort(value) {
    return REASONING_EFFORT_VALUES.includes(value);
}
export function resolveReasoningConfig(provider, modelId, env = process.env, options = {}) {
    const rawEffort = env[OPENWIKI_REASONING_EFFORT_ENV_KEY];
    if (rawEffort === undefined) {
        return undefined;
    }
    const effort = rawEffort.trim();
    if (!isReasoningEffort(effort)) {
        throw new Error(`Invalid ${OPENWIKI_REASONING_EFFORT_ENV_KEY}. Expected one of: ${REASONING_EFFORT_VALUES.join(", ")}.`);
    }
    const capability = provider === "openai-compatible"
        ? getOpenAiCompatibleReasoningCapability(modelId, env, options.useResponsesApi)
        : getReasoningCapability(provider, modelId, env);
    if (capability === undefined) {
        throw new Error(`${OPENWIKI_REASONING_EFFORT_ENV_KEY} is not supported for provider "${provider}" and model "${modelId}".`);
    }
    if (!capability.values.includes(effort)) {
        throw new Error(`Invalid ${OPENWIKI_REASONING_EFFORT_ENV_KEY} value "${effort}" for provider "${provider}" and model "${modelId}". Supported values: ${capability.values.join(", ")}.`);
    }
    return { effort, transport: capability.transport };
}
function getOpenAiCompatibleReasoningCapability(modelId, env, useResponsesApi = providerUsesResponsesApi("openai-compatible", modelId, env)) {
    if (!resolveOpenAiCompatibleReasoningEffortSupported(env)) {
        return undefined;
    }
    return {
        transport: useResponsesApi
            ? "responses-reasoning"
            : "chat-completions-reasoning-effort",
        values: REASONING_EFFORT_VALUES,
    };
}
